import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore, SessionListOptions} from '../../types/sessionStore.js';

it('lists only the authenticated session user with paging and ISO timestamps', async () => {
  const frames: unknown[] = [];
  const calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  const socket = {send: (raw: string) => frames.push(JSON.parse(raw))} as unknown as WebSocket;
  const session: ChatSession = {sessionId: 's1', userId: 'owner', entries: []};
  const store = {
    listFor: (userId: string | number, options?: SessionListOptions) => {
      calls.push({userId, options});
      return [{sessionId: 's2', createdAt: new Date('2026-01-01Z'), updatedAt: new Date('2026-01-02Z'), entryCount: 2}];
    },
  } as SessionStore;
  const handler = createMessageHandler({} as ChatOrchestrator, store);
  const before = {sessionId: 's3', updatedAt: '2026-01-03T00:00:00.000Z'};

  await handler(socket, session, {type: 'list_sessions', limit: 5, before, userId: 'other'});

  expect(calls).toEqual([{userId: 'owner', options: {limit: 5, before}}]);
  expect(frames).toEqual([
    {
      type: 'session_list',
      sessions: [
        {sessionId: 's2', createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-02T00:00:00.000Z', entryCount: 2},
      ],
    },
  ]);
});
